SELECT task_processing_id, tracking_process_id, request_tracking_id, task_processing_start_time, task_processing_result_msg, task_processing_status, task_processing_end_time FROM tracking_task_processing_info WHERE 1=1
and task_processing_id = #{taskProcessingId}
and tracking_process_id = #{trackingProcessId}
and request_tracking_id = #{requestTrackingId}
and task_processing_status = #{taskProcessingStatus}
order by task_processing_id desc

